const { createHmac } = require('crypto');

const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const site = ($env.CONVEX_SITE_URL ?? '').replace(/\/+$/, '');
if (!secret || !/^https?:\/\/[^\s]+$/.test(site)) {
  throw new Error('Set LENDLOOP_WEBHOOK_SECRET and CONVEX_SITE_URL for the overdue workflow');
}

const body = '{}';
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
return [{ json: { url: site + '/automation/overdue', body, timestamp, signature } }];

const { createHash } = require('crypto');

const response = $input.first().json;
if (!Array.isArray(response.loans)) {
  throw new Error('Convex overdue endpoint did not return a loans array');
}

const reminderDate = new Date().toISOString().slice(0, 10);
const seen = new Set();
const items = [];
for (const loan of response.loans) {
  if (!loan || typeof loan.loanId !== 'string' || !loan.loanId.trim()) {
    throw new Error('Convex overdue endpoint returned an invalid loan reference');
  }
  if (seen.has(loan.loanId)) continue;
  seen.add(loan.loanId);
  const reference = createHash('sha256')
    .update(loan.loanId + '.' + reminderDate)
    .digest('hex')
    .slice(0, 16);
  items.push({ json: { loanId: loan.loanId, reminderDate, reference } });
}
if (items.length === 0) {
  console.log('[lendloop] no overdue reminders due');
}
return items;

const { createHmac } = require('crypto');

const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const site = ($env.CONVEX_SITE_URL ?? '').replace(/\/+$/, '');
if (!secret || !/^https?:\/\/[^\s]+$/.test(site)) {
  throw new Error('Set LENDLOOP_WEBHOOK_SECRET and CONVEX_SITE_URL for the overdue workflow');
}

const { loanId, reminderDate, reference } = $input.first().json;
const body = JSON.stringify({ loanId, reminderDate });
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
return [{
  json: { url: site + '/automation/reminders', body, timestamp, signature, reference },
  pairedItem: { item: 0 },
}];

const { recorded } = $input.first().json;
const { reference } = $('Sign Reminder Claim').item.json;

if (typeof recorded !== 'boolean') {
  console.error('[lendloop] overdue reminder claim failed after retries: ' + reference);
  return [{ json: { outcome: 'failed', reference } }];
}
if (!recorded) {
  return [{ json: { outcome: 'skipped', reference } }];
}

// A successful atomic claim is required before logging a mock notification.
console.log('[lendloop] ' + JSON.stringify({
  delivery: 'mock',
  notification: 'overdue.reminder',
  reference,
}));
return [{ json: { outcome: 'recorded', reference } }];

const outcomes = $input.all().map(({ json }) => json.outcome);
const counts = {
  recorded: outcomes.filter((outcome) => outcome === 'recorded').length,
  skipped: outcomes.filter((outcome) => outcome === 'skipped').length,
  failed: outcomes.filter((outcome) => outcome === 'failed').length,
};
console.log('[lendloop] overdue reminder run ' + JSON.stringify(counts));
if (counts.failed > 0) {
  throw new Error(counts.failed + ' overdue reminder claim(s) failed after retries');
}
return [{ json: counts }];
